sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {


    var typeOfRequest = g_form.getValue('u_type_of_request');
    if (typeOfRequest == '3' || typeOfRequest == '1') {
        g_form.addOption('status', 'approach determination', 'Approach determination');
        g_form.addOption('status', 'hsbc only', 'HSBC only');
        g_form.addOption('status', 'BCT only or HSBC and BCT(no PCCW)', 'BCT only or HSBC and BCT(no PCCW)');
        g_form.addOption('status', 'HSBC and PCCW(no BCT)', 'HSBC and PCCW(no BCT)');
        g_form.addOption('status', 'Tri parties(jointly reply with PCCW)-1st reply', 'Tri parties(jointly reply with PCCW)-1st reply');
        g_form.addOption('status', 'Tri parties(jointly reply with PCCW)-subsequent reply', 'Tri parties(jointly reply with PCCW)-subsequent reply');
        g_form.addOption('status', 'Tri parties(individually HSBC reply)', 'Tri parties(individually HSBC reply)');
        g_form.removeOption('status', 'Enrol(ER)', 'Enrol(ER)');
        g_form.removeOption('status', 'Enrol(SEP)', 'Enrol(SEP)');
        g_form.removeOption('status', 'Enrol(others)', 'Enrol(others)');
        g_form.removeOption('status', 'Cont', 'Cont');
        g_form.removeOption('status', 'Term(not payment)', 'Term(not payment)');
        g_form.removeOption('status', 'Term(payment)', 'Term(payment)');
        g_form.removeOption('status', 'Payment Recon', 'Payment Recon');
        g_form.removeOption('status', 'Daily unit recon', 'Daily unit recon');
        g_form.removeOption('status', 'Daily Sch recon', 'Daily Sch recon');
        g_form.removeOption('status', 'AML/KYC', 'AML/KYC');

    } else if (typeOfRequest == '2') {
        g_form.addOption('status', 'Enrol(ER)', 'Enrol(ER)');
        g_form.addOption('status', 'Enrol(SEP)', 'Enrol(SEP)');
        g_form.addOption('status', 'Enrol(others)', 'Enrol(others)');
        g_form.addOption('status', 'Cont', 'Cont');
        g_form.addOption('status', 'Term(not payment)', 'Term(not payment)');
        g_form.addOption('status', 'Term(payment)', 'Term(payment)');
        g_form.addOption('status', 'Payment Recon', 'Payment Recon');
        g_form.addOption('status', 'Daily unit recon', 'Daily unit recon');
        g_form.addOption('status', 'Daily Sch recon', 'Daily Sch recon');
        g_form.addOption('status', 'AML/KYC', 'AML/KYC');
        g_form.removeOption('status', 'approach determination', 'Approach determination');
        g_form.removeOption('status', 'hsbc only', 'HSBC only');
        g_form.removeOption('status', 'BCT only or HSBC and BCT(no PCCW)', 'BCT only or HSBC and BCT(no PCCW)');
        g_form.removeOption('status', 'HSBC and PCCW(no BCT)', 'HSBC and PCCW(no BCT)');
        g_form.removeOption('status', 'Tri parties(jointly reply with PCCW)-1st reply', 'Tri parties(jointly reply with PCCW)-1st reply');
        g_form.removeOption('status', 'Tri parties(jointly reply with PCCW)-subsequent reply', 'Tri parties(jointly reply with PCCW)-subsequent reply');
        g_form.removeOption('status', 'Tri parties(individually HSBC reply)', 'Tri parties(individually HSBC reply)');

    }


}
